add_action( 'init', 'perfectpixel_upsells_above_tabs_setup' );
add_filter( 'woocommerce_upsell_display_args', 'perfectpixel_upsells_above_tabs_args', 20 );

function perfectpixel_upsells_above_tabs_setup() {
	remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_upsell_display', 15 );
	add_action( 'woocommerce_after_single_product_summary', 'woocommerce_upsell_display', 5 ); // Tabs are at 10.
}

function perfectpixel_upsells_above_tabs_args( $args ) {
	$args['posts_per_page'] = max( 1, (int) '{{upsells_above_count}}' );
	$args['columns']        = max( 1, (int) '{{upsells_above_columns}}' );
	return $args;
}
